ANSWERS['housing_move'] = ('''При переезде попроси уполномоченный орган нового региона объяснить включение по новому месту жительства и межведомственную передачу сведений. Правила установлены постановлением № 397.

Подготовь паспорт, сведения о прежнем включении и документы, подтверждающие новое место жительства; точный перечень уточни в принимающем органе. Сохрани заявление, его номер и письменные решения обоих регионов.

Не подавай отдельный отказ от права на жильё ради обещания «заново поставить в очередь». Если органы спорят о месте жительства или отказывают, покажи ответы бесплатному юристу. Учёба или временное пребывание в другом городе не всегда означают смену места жительства.''', ['list', 'law', 'lawyer'])
ANSWERS['exit_docs'] = ('''Перед выпуском попроси сотрудника центра вместе проверить, какие документы тебе передают, и составить перечень.

Для жилищного вопроса особенно нужны: документы о статусе, подтверждение включения в список с датой и решением, сведения о закреплённом жилье и правах на него, а при невозможности проживания — соответствующее решение. Также проверь паспорт, СНИЛС, полис ОМС, документы об образовании и имеющиеся судебные решения.

Это список для сверки, а не требование самостоятельно добыть каждый документ. Если чего-то нет, попроси письменное объяснение и помощь в восстановлении. Сделай копии, сохрани контакты опеки и ответственного за жилищный вопрос. Не оставляй оригиналы у посредника.''', ['law', 'list', 'lawyer'])
ANSWERS['purchases'] = ('''Сначала проверь, что уже есть в квартире и что исправно. Для первых дней обычно нужны постельные принадлежности, полотенце, минимум посуды, продукты, мыло и простые средства уборки.

Раздели покупки на «нужно сейчас» и «может подождать». Не покупай технику в кредит только ради полного комплекта. Сохраняй чеки и инструкции; неисправную электрику и газовое оборудование поручай специалистам.

Если не хватает средств на самое необходимое, обратись в соцзащиту за срочной помощью и открой «Где могут помочь» в главном меню. Условия выдачи вещей и продуктов уточняй у организации заранее.''', ['gu', 'clean'])

INTROS = {
 'housing': ('Давай разберёмся с жильём 🏡\n\nДля аренды открой «Поиск жилья». Для квартиры от государства, договора, платежей и бытовых вопросов выбери тему ниже. В ответах есть конкретные шаги и кнопки официальных сервисов и законов. Если сейчас угрожают или выгоняют — начни с ветки о выселении.', ['lawyer']),
 'state_housing': ('Квартира от государства\n\nНачни со своего этапа: проверить право и включение в список, подать заявление, принять квартиру или разобраться с задержкой. В каждом ответе есть порядок действий и ссылки. Правила твоего региона уточняются в уполномоченном органе.', ['law', 'gu']),
 'hq_sale': ('Когда можно продать жильё?\n\nСначала выясни, какой у тебя договор: специализированный наём, социальный наём или собственность. От этого зависит возможность продажи и сдачи. Получение ключей и истечение пяти лет сами по себе не делают тебя собственником.', ['law', 'egrn']),
 'rent': ('Как снять жильё?\n\nНачни с полного бюджета: наём, обеспечительный платёж, комиссия и ЖКУ. Затем проверь собственника, договор и акт передачи. Ниже — памятки для каждого этапа и ссылки на документы.', ['gk', 'egrn']),
 'utilities': ('Коммунальные платежи\n\nРазберём квитанцию, показания, срок оплаты и помощь при долге. Для обращений и информации о доме можно использовать ГИС ЖКХ. Неясную сумму сначала попроси объяснить письменно.', ['dom', 'subsidy']),
 'household': ('Бытовуха\n\nНеобязательно сразу уметь всё по дому. Выбери вопрос про вещи, еду, уборку или соседей. Для газа и протечки есть отдельные действия; при непосредственной опасности звони 112.', ['clean', 'gas']),
 'housing_problem': ('Что делать, если тебя выселяют?\n\nПри угрозах или насилии уйди в безопасное место и позвони 112/102. Если опасности сейчас нет, сохрани договор и требование выехать, выбери свою ситуацию ниже. Здесь есть шаги для защиты прав, бесплатный юрист и помощь с ночлегом.', ['lawyer', 'prosecutor']),
}

def configure(original):
    config = deepcopy(original)
    nodes = {n['id']: n for n in config['nodes']}
    for key, (title, url) in SOURCES.items():
        config['sources'][key] = dict(title=title, url=url, checked=DATE,
            scope='Жильё: справочные шаги и сервисы; регион и условия выбираются у источника',
            verification='Текст/назначение сверены по веб-источникам; форма может требовать входа ЕСИА')
    updates = dict(ANSWERS)
    updates.update({key: ANSWERS[target] for key, target in EXTRA.items()})
    updates.update(INTROS)
    for key, (text, refs) in updates.items():
        node = nodes[key]
        if key not in INTROS:
            text = node['title'] + '\n\n' + text
        node.update(text=text, adult_text='Этот ответ написан для ребёнка или выпускника.\n\n' + text,
            sources=['h30_' + s for s in refs], content_status='reviewed_reference', tasks=[])
        node['editorial_sources'] = list(node['sources'])
        node['editorial_note'] = 'Проверено 30.09.2026: конкретные действия и видимые ссылки.'
    # Keep old alternative entry screens useful without changing any route.
    for key in ['housing_rights', 'received', 'docs_housing', 'help', 'help_registry']:
        nodes[key]['sources'] = ['h30_lawyer', 'h30_gu']
    # Prepared LLM materials must not retain superseded disclaimers or empty references.
    for material in config.get('materials', []):
        key = material['id'].removeprefix('prepared_')
        if key in updates:
            material.update(text=nodes[key]['text'], sources=nodes[key]['sources'], checked=DATE)
        elif material.get('enabled') and material.get('branches') == ['housing']:
            keys = (['hq_state_housing_right', 'hq_state_housing_apply', 'hq_state_housing_delay']
                    if material['id'] == 'material_housing_rights' else ['hq_hq_sale_owner', 'hq_hq_sale_let'])
            material.update(text='\n\n'.join(nodes[k]['text'] for k in keys),
                sources=list(dict.fromkeys(s for k in keys for s in nodes[k]['sources'])), checked=DATE)
    validate(config)
    return config
